#!/usr/bin/env bash
# Builds HabitTech as an installable Android APK.
#
# Requirements: Flutter (stable) with the Android SDK set up. Check with
#   flutter doctor
#
# Usage (from the project root):   bash tool/build_apk.sh
# Output:                          dist/HabitTech.apk
set -euo pipefail

cd "$(dirname "$0")/.."

if ! command -v flutter >/dev/null 2>&1; then
  echo "Flutter was not found on your PATH. Install it from https://docs.flutter.dev/get-started/install" >&2
  exit 1
fi

# The Android project files are generated by Flutter itself so they always
# match your installed Flutter version. Existing files are never overwritten.
if [ ! -d android ]; then
  echo "==> Generating the Android project"
  flutter create --platforms=android --org com.habittech --project-name habittech --description "HabitTech" .
  # `flutter create` adds a counter-app test that does not apply to HabitTech.
  rm -f test/widget_test.dart
fi

# Show the app name as "HabitTech" on the home screen.
MANIFEST="android/app/src/main/AndroidManifest.xml"
if [ -f "$MANIFEST" ]; then
  sed -i.bak 's/android:label="[^"]*"/android:label="HabitTech"/' "$MANIFEST" && rm -f "$MANIFEST.bak"
fi

echo "==> Fetching packages"
flutter pub get

echo "==> Running tests"
flutter test

echo "==> Building the release APK"
flutter build apk --release

mkdir -p dist
cp build/app/outputs/flutter-apk/app-release.apk dist/HabitTech.apk
echo
echo "Done: dist/HabitTech.apk"
echo "Copy it to your phone and open it. Android will ask you to allow installs from this source."
